+void ScreenLockerKcm::loadNetworks()
+{
+    qDBusRegisterMetaType<NMVariantMapMap>();
+
+    auto getProperty = [](const QString &path, const QString &interface, const QString &property) {
+        QDBusMessage message = QDBusMessage::createMethodCall(s_nmService, path, QStringLiteral("org.freedesktop.DBus.Properties"), QStringLiteral("Get"));
+        message << interface << property;
+        return QDBusConnection::systemBus().asyncCall(message);
+    };
+
+    auto activeWatcher =
+        new QDBusPendingCallWatcher(getProperty(QStringLiteral("/org/freedesktop/NetworkManager"), s_nmService, QStringLiteral("ActiveConnections")), this);
+    connect(activeWatcher, &QDBusPendingCallWatcher::finished, this, [this, getProperty](QDBusPendingCallWatcher *self) {
+        self->deleteLater();
+        QDBusPendingReply<QDBusVariant> reply = *self;
+        if (!reply.isValid()) {
+            return;
+        }
+        QList<QDBusObjectPath> paths;
+        reply.value().variant().value<QDBusArgument>() >> paths;
+        for (const QDBusObjectPath &path : std::as_const(paths)) {
+            auto uuidWatcher = new QDBusPendingCallWatcher(
+                getProperty(path.path(), QStringLiteral("org.freedesktop.NetworkManager.Connection.Active"), QStringLiteral("Uuid")),
+                this);
+            connect(uuidWatcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *self) {
+                self->deleteLater();
+                QDBusPendingReply<QDBusVariant> reply = *self;
+                if (reply.isValid()) {
+                    m_connectedNetworks.insert(reply.value().variant().toString());
+                    Q_EMIT networksChanged();
+                }
+            });
+        }
+    });
+
+    QDBusMessage listMessage = QDBusMessage::createMethodCall(s_nmService,
+                                                              QStringLiteral("/org/freedesktop/NetworkManager/Settings"),
+                                                              QStringLiteral("org.freedesktop.NetworkManager.Settings"),
+                                                              QStringLiteral("ListConnections"));
+    auto listWatcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(listMessage), this);
+    connect(listWatcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *self) {
+        self->deleteLater();
+        QDBusPendingReply<QList<QDBusObjectPath>> reply = *self;
+        if (!reply.isValid()) {
+            return;
+        }
+        for (const QDBusObjectPath &path : reply.value()) {
+            QDBusMessage message = QDBusMessage::createMethodCall(s_nmService,
+                                                                  path.path(),
+                                                                  QStringLiteral("org.freedesktop.NetworkManager.Settings.Connection"),
+                                                                  QStringLiteral("GetSettings"));
+            auto settingsWatcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(message), this);
+            connect(settingsWatcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *self) {
+                self->deleteLater();
+                QDBusPendingReply<NMVariantMapMap> reply = *self;
+                if (!reply.isValid()) {
+                    return;
+                }
+                const QVariantMap connection = reply.value().value(QStringLiteral("connection"));
+                const QString type = connection.value(QStringLiteral("type")).toString();
+                if (type == QLatin1String("802-11-wireless") || type == QLatin1String("802-3-ethernet")) {
+                    m_networkNames.insert(connection.value(QStringLiteral("uuid")).toString(), connection.value(QStringLiteral("id")).toString());
+                    Q_EMIT networksChanged();
+                }
+            });
+        }
+    });
+}
+
+QVariantList ScreenLockerKcm::networks() const
+{
+    QVariantList networks;
+    for (auto it = m_networkNames.cbegin(); it != m_networkNames.cend(); ++it) {
+        networks.append(QVariantMap{
+            {QStringLiteral("uuid"), it.key()},
+            {QStringLiteral("name"), it.value()},
+            {QStringLiteral("connected"), m_connectedNetworks.contains(it.key())},
+        });
+    }
+    std::sort(networks.begin(), networks.end(), [](const QVariant &a, const QVariant &b) {
+        const QVariantMap left = a.toMap();
+        const QVariantMap right = b.toMap();
+        if (left[QStringLiteral("connected")] != right[QStringLiteral("connected")]) {
+            return left[QStringLiteral("connected")].toBool();
+        }
+        return left[QStringLiteral("name")].toString().localeAwareCompare(right[QStringLiteral("name")].toString()) < 0;
+    });
+    return networks;
 }

