--- /dev/null
+++ b/trustednetwork_inhibition.cpp
@@ -0,0 +1,121 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+SPDX-License-Identifier: GPL-2.0-or-later
+*/
+#include "trustednetwork_inhibition.h"
+
+#include <QDBusArgument>
+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QDBusObjectPath>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
+#include <QDBusServiceWatcher>
+#include <QDBusVariant>
+
+#include <memory>
+
+static const QString s_nmService = QStringLiteral("org.freedesktop.NetworkManager");
+static const QString s_nmPath = QStringLiteral("/org/freedesktop/NetworkManager");
+static const QString s_nmActiveConnectionInterface = QStringLiteral("org.freedesktop.NetworkManager.Connection.Active");
+static const QString s_propertiesInterface = QStringLiteral("org.freedesktop.DBus.Properties");
+
+static QDBusPendingCall getProperty(const QString &path, const QString &interface, const QString &property)
+{
+    QDBusMessage message = QDBusMessage::createMethodCall(s_nmService, path, s_propertiesInterface, QStringLiteral("Get"));
+    message << interface << property;
+    return QDBusConnection::systemBus().asyncCall(message);
+}
+
+TrustedNetworkInhibition::TrustedNetworkInhibition(QObject *parent)
+    : QObject(parent)
+    , m_networkManagerWatcher(new QDBusServiceWatcher(s_nmService,
+                                                      QDBusConnection::systemBus(),
+                                                      QDBusServiceWatcher::WatchForUnregistration | QDBusServiceWatcher::WatchForRegistration,
+                                                      this))
+{
+    connect(m_networkManagerWatcher, &QDBusServiceWatcher::serviceRegistered, this, &TrustedNetworkInhibition::update);
+    connect(m_networkManagerWatcher, &QDBusServiceWatcher::serviceUnregistered, this, &TrustedNetworkInhibition::update);
+
+    QDBusConnection::systemBus().connect(s_nmService,
+                                         s_nmPath,
+                                         s_propertiesInterface,
+                                         QStringLiteral("PropertiesChanged"),
+                                         this,
+                                         SLOT(propertiesChanged(QString, QVariantMap, QStringList)));
+}
+
+TrustedNetworkInhibition::~TrustedNetworkInhibition() = default;
+
+void TrustedNetworkInhibition::setTrustedNetworks(const QStringList &uuids)
+{
+    if (m_trustedNetworks == uuids) {
+        return;
+    }
+    m_trustedNetworks = uuids;
+    update();
+}
+
+void TrustedNetworkInhibition::propertiesChanged(const QString &interface, const QVariantMap &changedProperties, const QStringList &invalidatedProperties)
+{
+    Q_UNUSED(interface)
+    if (changedProperties.contains(QStringLiteral("ActiveConnections")) || invalidatedProperties.contains(QStringLiteral("ActiveConnections"))) {
+        update();
+    }
+}
+
+void TrustedNetworkInhibition::update()
+{
+    const uint serial = ++m_updateSerial;
+    if (m_trustedNetworks.isEmpty()) {
+        setInhibited(false);
+        return;
+    }
+
+    auto watcher = new QDBusPendingCallWatcher(getProperty(s_nmPath, s_nmService, QStringLiteral("ActiveConnections")), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, serial](QDBusPendingCallWatcher *self) {
+        self->deleteLater();
+        if (serial != m_updateSerial) {
+            return;
+        }
+        QDBusPendingReply<QDBusVariant> reply = *self;
+        QList<QDBusObjectPath> activeConnections;
+        if (reply.isValid()) {
+            reply.value().variant().value<QDBusArgument>() >> activeConnections;
+        }
+        if (activeConnections.isEmpty()) {
+            setInhibited(false);
+            return;
+        }
+
+        auto pending = std::make_shared<qsizetype>(activeConnections.size());
+        for (const QDBusObjectPath &path : std::as_const(activeConnections)) {
+            auto uuidWatcher = new QDBusPendingCallWatcher(getProperty(path.path(), s_nmActiveConnectionInterface, QStringLiteral("Uuid")), this);
+            connect(uuidWatcher, &QDBusPendingCallWatcher::finished, this, [this, serial, pending](QDBusPendingCallWatcher *self) {
+                self->deleteLater();
+                if (serial != m_updateSerial) {
+                    return;
+                }
+                QDBusPendingReply<QDBusVariant> reply = *self;
+                if (reply.isValid() && m_trustedNetworks.contains(reply.value().variant().toString())) {
+                    // stop the other replies from changing the result
+                    ++m_updateSerial;
+                    setInhibited(true);
+                } else if (--*pending == 0) {
+                    setInhibited(false);
+                }
+            });
+        }
+    });
+}
+
+void TrustedNetworkInhibition::setInhibited(bool inhibited)
+{
+    if (m_inhibited != inhibited) {
+        m_inhibited = inhibited;
+        Q_EMIT inhibitedChanged();
+    }
+}
+
+#include "moc_trustednetwork_inhibition.cpp"
