+
+SPDX-License-Identifier: GPL-2.0-or-later
+*/
+#pragma once
+
+#include <QObject>
+#include <QStringList>
+
+class QDBusServiceWatcher;
+
+/**
+ * Inhibits the automatic lock while NetworkManager has an active connection
+ * whose UUID is in the list of trusted networks.
+ */
+class TrustedNetworkInhibition : public QObject
+{
+    Q_OBJECT
+public:
+    explicit TrustedNetworkInhibition(QObject *parent = nullptr);
+    ~TrustedNetworkInhibition() override;
+
+    void setTrustedNetworks(const QStringList &uuids);
+
+    bool isInhibited() const
+    {
+        return m_inhibited;
+    }
+
+    Q_SIGNAL void inhibitedChanged();
+
+private Q_SLOTS:
+    void propertiesChanged(const QString &interface, const QVariantMap &changedProperties, const QStringList &invalidatedProperties);
+
+private:
+    void update();
+    void setInhibited(bool inhibited);
+
+    QDBusServiceWatcher *m_networkManagerWatcher;
+    QStringList m_trustedNetworks;
+    bool m_inhibited = false;
+    uint m_updateSerial = 0;
+};
